<?php $isHistory=!empty($deliverySearch['history']); $listPage=$isHistory?'history':'deliveries'; ?>
<section class="card spaced" id="deliveries"><h2><?= $isHistory ? 'Historial de historias enviadas' : 'Solicitudes y envíos' ?></h2><p class="muted"><?= $isHistory ? 'Solicitudes aprobadas automáticamente y con envío aceptado por el servidor de correo. Los casos reabiertos pasan a Solicitudes y envíos hasta completar un nuevo envío.' : 'Busca al paciente y consulta el seguimiento de su historia clínica.' ?></p>
<form method="get" class="delivery-search"><input type="hidden" name="page" value="<?= $listPage ?>"><label for="delivery-query">Nombre, radicado o número de documento<input id="delivery-query" type="search" name="q" maxlength="160" placeholder="Ej.: nombre completo, HC-… o cédula" value="<?= h($deliverySearch['query']) ?>"></label><button class="button primary" type="submit">Buscar</button><?php if ($deliverySearch['query'] !== ''): ?><a class="button secondary" href="?page=<?= $listPage ?>">Limpiar</a><?php endif ?></form>
