<?php else: ?>
<?php if ($isHistory): require __DIR__ . '/delivery-history-rows.php'; else: ?><div class="table-wrap"><table class="responsive-table" role="table"><thead role="rowgroup"><tr role="row"><th scope="col" role="columnheader">Paciente</th><th scope="col" role="columnheader">Radicado / fecha</th><th scope="col" role="columnheader">Correo de entrega</th><th scope="col" role="columnheader">Estado</th><th scope="col" role="columnheader">Envíos</th><th scope="col" role="columnheader">Ver</th></tr></thead><tbody role="rowgroup">
<?php foreach ($deliverySearch['rows'] as $row): ?><tr role="row"><td role="cell" data-label="Paciente"><strong><?= h($row['claimed_name']) ?></strong><small><?= $row['document_number'] ? h($row['document_type'].' '.$row['document_number']) : 'Documento no conservado en esta solicitud antigua' ?></small></td><td role="cell" data-label="Radicado / fecha"><?= h($row['reference']) ?><small><?= h($row['created_at']) ?></small></td><td role="cell" data-label="Correo de entrega" class="delivery-email"><?= h($row['contact_email'] ?? '—') ?></td><td role="cell" data-label="Estado"><?php if ($row['case_pending']): ?><span class="pill case-pending">Pendiente de gestión</span><small>Reabierto <?= h($row['case_reopened_at']) ?></small><?php endif ?><span class="pill"><?= h($labels[$row['status']] ?? $row['status']) ?></span><?php if ($row['last_error']): ?><small class="danger">Último envío con error</small><?php endif ?></td><td role="cell" data-label="Envíos"><?= (int)$row['deliveries'] ?></td><td role="cell" data-label="Ver"><a class="button secondary eye-button" data-delivery-modal aria-haspopup="dialog" aria-controls="delivery-modal" href="?page=delivery&amp;id=<?= (int)$row['id'] ?>&amp;q=<?= rawurlencode($deliverySearch['query']) ?>&amp;p=<?= (int)$deliverySearch['page'] ?>" aria-label="Ver envío de <?= h($row['reference']) ?>" title="Ver detalle del envío"><svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><path d="M2 12s3.5-7 10-7 10 7 10 7-3.5 7-10 7S2 12 2 12Z"/><circle cx="12" cy="12" r="3"/></svg></a></td></tr><?php endforeach ?>
</tbody></table></div><?php endif ?>
<nav class="delivery-pagination" aria-label="Páginas de solicitudes"><?php if ($deliverySearch['page']>1): ?><a class="button secondary" href="?page=<?= $listPage ?>&amp;q=<?= rawurlencode($deliverySearch['query']) ?>&amp;p=<?= $deliverySearch['page']-1 ?>">← Anterior</a><?php endif ?><span class="muted">Página <?= (int)$deliverySearch['page'] ?> de <?= (int)$deliverySearch['pages'] ?></span><?php if ($deliverySearch['page']<$deliverySearch['pages']): ?><a class="button secondary" href="?page=<?= $listPage ?>&amp;q=<?= rawurlencode($deliverySearch['query']) ?>&amp;p=<?= $deliverySearch['page']+1 ?>">Siguiente →</a><?php endif ?></nav>
<?php endif ?></section>
